namespace IntoChat.OS.Architecture.Tests.Unit;

// The ratchet pins are regenerated by explicit capture writers. This fact runs the pure writers into a temp
// directory and holds every committed pin to what a fresh capture produces, so a stale pin cannot hide behind
// the directional ratchets (they only fail one way). Captures that are additive-only are enforced by
// scripts/capture-all; this fact only says "run it".
public sealed class PinFreshnessFacts
{
    private static readonly string[] Files =
    [
        "GrainFactoryOwners.json",
        "OrleansReferenceOwners.json",
        "ConfigurationKeyOwners.json",
        "TestTierBaseline.json",
        "CollectionCompatibilitySamples.json",
        "SynapseWordAllowlist.json",
        FrameworkHasNoVendorSdksFacts.BaselineFile,
        AppsHaveNoModuleIdsFacts.BaselineFile,
        NamespaceSchemeFacts.BaselineFile,
    ];

    [Fact]
    public void CommittedPinsEqualAFreshCapture()
    {
        var fresh = Directory.CreateTempSubdirectory("pin-freshness-");
        try
        {
            using (CaptureWriter.RedirectTo(fresh.FullName))
            {
                new RuntimeBoundaryFacts().CaptureGrainFactoryOwners();
                new RuntimeBoundaryFacts().CaptureOrleansReferenceOwners();
                new ConfigurationKeyFacts().CaptureConfigurationKeyOwners();
                new TestTierRules().CaptureTestTierBaseline();
                new CollectionCompatibilityFacts().CaptureCollectionCompatibilitySamples();
                new SynapseWordFacts().CaptureSynapseWordAllowlist();
                new FrameworkHasNoVendorSdksFacts().CaptureFrameworkVendorBaseline();
                new AppsHaveNoModuleIdsFacts().CaptureAppsModuleIdBaseline();
                new NamespaceSchemeFacts().CaptureNamespaceSchemeBaseline();
            }
            var stale = new List<string>();
            foreach (var file in Files)
            {
                if (Normalise(File.ReadAllText(CaptureWriter.Path(file))) != Normalise(File.ReadAllText(Path.Combine(fresh.FullName, file))))
                {
                    stale.Add(file);
                }
            }
            if (Normalise(File.ReadAllText(ContractManifest.BaselinePath)) != Normalise(ContractManifest.Capture().ToJson()))
            {
                stale.Add(ContractManifest.FileName);
            }
            Assert.True(stale.Count == 0,
                "Stale pins: " + string.Join(", ", stale) + ". Regenerate with `pwsh scripts/capture-all.ps1` (or `scripts/capture-all.sh`); "
                + "removals and changed values need -AllowBreaking and review.");
        }
        finally
        {
            fresh.Delete(recursive: true);
        }
    }

    private static string Normalise(string text) => text.ReplaceLineEndings("\n");
}
